.summary-audio-icon svg { width: 17px; height: 17px; }
.summary-audio-toggle:hover .summary-audio-icon, .is-playing .summary-audio-icon { background: rgba(179, 137, 61, .13); }
.summary-audio-toggle:active .summary-audio-icon { transform: scale(.92); }
