.summary-audio-copy { display: flex; flex-direction: column; gap: .16rem; font-family: 'Quattrocento Sans', sans-serif; }
.summary-audio-label { font-size: .87rem; font-weight: 600; line-height: 1.25; }
.summary-audio-byline { font-size: .73rem; color: var(--view-muted, #777); line-height: 1.3; }
.summary-audio-time { font: .7rem/1.2 system-ui, sans-serif; font-variant-numeric: tabular-nums; color: var(--view-muted, #777); white-space: nowrap; }
.summary-audio-seek { display: block; width: 100%; height: 24px; margin: .25rem 0 0; accent-color: var(--view-accent, #99713b); cursor: pointer; }
.summary-audio-error { max-width: 23rem; margin: .5rem 0 0; font-size: .8rem; line-height: 1.4; color: var(--view-muted, #777); }
.summary-audio-spinner { width: 14px; height: 14px; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: audio-spin 900ms linear infinite; }
